parameters.jsCode:
const body = $input.first().json.body;
const required = ['document_text', 'document_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (body.document_text.trim().length < 100) return [{ json: { valid: false, error: 'document_text too short' } }];
const docTypes = ['contract', 'nda', 'terms_of_service', 'privacy_policy', 'employment_agreement', 'lease', 'software_license', 'partnership_agreement', 'service_agreement', 'settlement', 'other'];
const docType = docTypes.includes(body.document_type) ? body.document_type : 'other';
const audiences = ['founder', 'non_lawyer_business', 'employee', 'technical_team', 'general'];
const audience = audiences.includes(body.audience) ? body.audience : 'non_lawyer_business';
return [{ json: {
  valid: true,
  documentText: body.document_text.trim().slice(0, 15000),
  documentType: docType,
  documentTitle: body.document_title || '',
  audience,
  partyRole: body.party_role || '',
  specificConcerns: (body.specific_concerns || '').slice(0, 400),
  jurisdiction: body.jurisdiction || '',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Summarize this legal document.

Document type: {{ $json.documentType.replace(/_/g,' ') }}
Document title: {{ $json.documentTitle || 'not provided' }}
Reader's role/party: {{ $json.partyRole || 'not specified' }}
Audience: {{ $json.audience.replace(/_/g,' ') }}
Jurisdiction: {{ $json.jurisdiction || 'not specified' }}
Specific concerns: {{ $json.specificConcerns || 'none' }}

Document text:
{{ $json.documentText }}

Return this JSON:
{
  "document_overview": "2-3 sentences: what this document is, who the parties are, and what it accomplishes",
  "plain_english_summary": "4-6 sentences: what this document means in plain language for someone in the reader's position — what they're agreeing to, what they get, what they give up",
  "key_provisions": [
    {
      "title": "provision name",
      "plain_english": "what this clause means in plain language",
      "implications": "what this means practically for the reader — consequences, restrictions, or rights created",
      "severity": "neutral | noteworthy | concerning | critical"
    }
  ],
  "obligations_on_reader": ["specific things the reader must do, must not do, or must provide"],
  "rights_granted_to_reader": ["specific rights the reader gains under this agreement"],
  "red_flags": [
    {
      "clause": "brief description of the clause or section",
      "concern": "why this is unusual or potentially problematic",
      "typical_alternative": "what this clause typically looks like in a balanced agreement"
    }
  ],
  "missing_protections": ["things typically found in this document type that are absent here"],
  "termination_summary": "plain English explanation of how the agreement ends and what happens when it does",
  "liability_and_indemnification": "plain English summary of what each party is responsible for if things go wrong",
  "key_dates_and_deadlines": ["specific dates, notice periods, or renewal windows to be aware of"],
  "questions_for_lawyer": ["4-6 specific questions to raise with legal counsel before signing — based on actual content in this document"],
  "overall_risk_assessment": "one of: low | moderate | elevated | high",
  "risk_rationale": "1-2 sentences explaining the overall risk level"
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let summary;
try { summary = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
summary._meta = { documentType: input.documentType, documentTitle: input.documentTitle, audience: input.audience, partyRole: input.partyRole, replyEmail: input.replyEmail };
return [{ json: summary }];

const s = $input.first().json;
const m = s._meta;
function esc(t) { return String(t||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const riskConfig = {low:{color:'#16a34a',bg:'#f0fdf4',label:'Low Risk'}, moderate:{color:'#2563eb',bg:'#eff6ff',label:'Moderate Risk'}, elevated:{color:'#d97706',bg:'#fffbeb',label:'Elevated Risk'}, high:{color:'#dc2626',bg:'#fef2f2',label:'High Risk'}};
const rc = riskConfig[s.overall_risk_assessment] || riskConfig.moderate;

const sevColors = {neutral:'#6b7280', noteworthy:'#2563eb', concerning:'#d97706', critical:'#dc2626'};
const sevBgs = {neutral:'#f9fafb', noteworthy:'#eff6ff', concerning:'#fffbeb', critical:'#fef2f2'};

const keyProvisions = (s.key_provisions||[]).map(p => `
  <div style="border-left:3px solid ${sevColors[p.severity]||'#6b7280'};padding:12px 16px;background:${sevBgs[p.severity]||'#f9fafb'};border-radius:0 6px 6px 0;margin-bottom:10px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">
      <span style="font-size:14px;font-weight:600">${esc(p.title)}</span>
      <span style="background:${sevColors[p.severity]||'#6b7280'}22;color:${sevColors[p.severity]||'#6b7280'};font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px">${esc(p.severity)}</span>
    </div>
    <div style="font-size:14px;color:#374151;line-height:1.65;margin-bottom:6px">${esc(p.plain_english)}</div>
    <div style="font-size:13px;color:#555;font-style:italic">${esc(p.implications)}</div>
  </div>`).join('');

const redFlags = (s.red_flags||[]).map(rf => `
  <div style="border:1px solid #fecaca;border-radius:6px;margin-bottom:10px;overflow:hidden">
    <div style="background:#fef2f2;padding:8px 14px;font-size:13px;font-weight:600;color:#7f1d1d">${esc(rf.clause)}</div>
    <div style="padding:10px 14px">
      <div style="font-size:13px;color:#dc2626;margin-bottom:4px"><strong>Concern:</strong> ${esc(rf.concern)}</div>
      <div style="font-size:13px;color:#374151"><strong>Typically:</strong> ${esc(rf.typical_alternative)}</div>
    </div>
  </div>`).join('');

const obligations = (s.obligations_on_reader||[]).map(o => `<li style="font-size:14px;margin-bottom:6px;line-height:1.5">${esc(o)}</li>`).join('');
const rights = (s.rights_granted_to_reader||[]).map(r => `<li style="font-size:14px;margin-bottom:6px;line-height:1.5;color:#166534">${esc(r)}</li>`).join('');
const missing = (s.missing_protections||[]).map(mp => `<div style="font-size:13px;color:#92400e;padding:4px 0">◦ ${esc(mp)}</div>`).join('');
const questions = (s.questions_for_lawyer||[]).map((q,i) => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #eff6ff;color:#1e40af">${i+1}. ${esc(q)}</div>`).join('');
const dates = (s.key_dates_and_deadlines||[]).map(d => `<div style="font-size:14px;padding:5px 0;border-bottom:1px solid #f3f4f6">${esc(d)}</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:Georgia,'Times New Roman',serif;color:#1a1a1a">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#1e293b;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:5px">${esc(m.documentType.replace(/_/g,' '))}${m.partyRole ? ' · ' + esc(m.partyRole) + ' perspective' : ''}</div>
    <div style="font-size:18px;font-weight:700">${esc(m.documentTitle||'Legal Document Summary')}</div>
    <div style="font-size:12px;color:#94a3b8;margin-top:4px;font-family:sans-serif">Not legal advice — for informational purposes only</div>
  </div>
  <div style="background:${rc.bg};padding:14px 28px;border:1px solid ${rc.color}44;border-top:none">
    <div style="display:flex;align-items:center;gap:12px">
      <span style="background:${rc.color};color:#fff;font-size:12px;font-weight:700;padding:4px 14px;border-radius:12px">${rc.label}</span>
      <div style="font-size:13px;color:#555">${esc(s.risk_rationale)}</div>
    </div>
  </div>
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px;font-family:sans-serif">What this document does</div>
    <p style="font-size:14px;line-height:1.75;color:#374151;margin:0 0 12px">${esc(s.document_overview)}</p>
    <p style="font-size:15px;line-height:1.8;color:#1a1a1a;font-style:italic;border-left:3px solid #e5e7eb;padding-left:14px;margin:0">${esc(s.plain_english_summary)}</p>
  </div>
  ${keyProvisions ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px;font-family:sans-serif">Key provisions</div>
    ${keyProvisions}
  </div>` : ''}
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px">
      ${obligations ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#dc2626;margin-bottom:7px;font-family:sans-serif">Your obligations</div><ul style="padding-left:18px;margin:0">${obligations}</ul></div>` : ''}
      ${rights ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#16a34a;margin-bottom:7px;font-family:sans-serif">Your rights</div><ul style="padding-left:18px;margin:0">${rights}</ul></div>` : ''}
    </div>
  </div>
  ${redFlags ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:10px;font-family:sans-serif">Red flags to discuss with your lawyer</div>
    ${redFlags}
  </div>` : ''}
  ${missing ? `<div style="background:#fffbeb;padding:14px 28px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:7px;font-family:sans-serif">Missing protections</div>
    ${missing}
  </div>` : ''}
  ${s.liability_and_indemnification || s.termination_summary ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    ${s.termination_summary ? `<div style="margin-bottom:10px"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px;font-family:sans-serif">Termination</div><div style="font-size:14px;color:#374151;line-height:1.65">${esc(s.termination_summary)}</div></div>` : ''}
    ${s.liability_and_indemnification ? `<div><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px;font-family:sans-serif">Liability & indemnification</div><div style="font-size:14px;color:#374151;line-height:1.65">${esc(s.liability_and_indemnification)}</div></div>` : ''}
  </div>` : ''}
  ${dates ? `<div style="background:#fff;padding:14px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:7px;font-family:sans-serif">Key dates & deadlines</div>
    ${dates}
  </div>` : ''}
  ${questions ? `<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px;font-family:sans-serif">Ask your lawyer these questions</div>
    ${questions}
  </div>` : ''}
  <div style="background:#1e293b;color:#475569;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Legal Document Summarizer · Not legal advice · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, documentType: m.documentType, riskLevel: s.overall_risk_assessment, summary: s } }];
